INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(1,'좋은 아침!/안녕!','你早！','["你","早"]','아침에 상대에게 건네는 인사입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(2,'축하합니다!','恭喜恭喜！','["恭喜","恭喜"]','축하할 때 쓰는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(3,'매우 죄송합니다!','很抱歉！','["很","抱歉"]','사과를 강하게 나타내는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(4,'정말 죄송합니다!','很道歉！','["很","道歉"]','자료에 제시된 사과 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(5,'폐를 끼쳤습니다.','麻烦你了。','["麻烦","你","了"]','상대에게 번거로움을 끼쳤을 때 쓰는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(6,'양해해 주세요.','请原谅。','["请","原谅"]','상대의 용서나 양해를 구하는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(7,'당신의 성은 어떻게 되시나요?','您贵姓？','["您","贵姓"]','상대의 성을 공손하게 묻는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(8,'성이 무엇이니?','你姓什么？','["你","姓","什么"]','상대의 성을 묻는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(9,'저는 김 씨이고, 이름은 김대한입니다.','我姓金。叫金大韩。','["我","姓","金","叫","金大韩"]','자료에 제시된 성과 이름을 답하는 예문입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(10,'제 소개 좀 할게요.','我来自我介绍一下。','["我","来","自我介绍","一下"]','자료 원문 표현을 그대로 수록했습니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(11,'제가 소개해 드릴게요.','我给你介绍一下。','["我","给","你","介绍","一下"]','상대에게 누군가를 소개하겠다고 말하는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(12,'만나서 기뻐요.','见到你很高兴。','["见到","你","很","高兴"]','처음 만나 반가움을 나타내는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(13,'알게 되어 영광입니다.','认识你很荣幸。','["认识","你","很","荣幸"]','상대를 알게 된 것을 영광스럽게 여기는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(14,'예전부터 존함을 들었습니다.','久仰久仰！','["久仰","久仰"]','상대의 명성을 예전부터 들었다는 인사 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(15,'축하합니다!','祝贺你！','["祝贺","你"]','상대를 축하하는 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(16,'새해 즐겁게 보내!','新年快乐！','["新年","快乐"]','새해 축하 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(17,'메리 크리스마스!','圣诞快乐！','["圣诞","快乐"]','성탄절 축하 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(18,'생일 축하합니다.','祝你生日快乐！','["祝","你","生日","快乐"]','생일 축하 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(19,'대학에 합격하세요!','祝你考上大学！','["祝","你","考上","大学"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(20,'행운이 있길 빕니다!','祝你好运！','["祝","你","好运"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(21,'건강하세요!','祝你身体健康！','["祝","你","身体","健康"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(22,'성공하세요!','祝你成功！','["祝","你","成功"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(23,'평안하길 바라!','祝你平安！','["祝","你","平安"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(24,'행복하길 바라!','祝你幸福！','["祝","你","幸福"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(25,'주말 잘 보내세요!','祝你周末愉快！','["祝","你","周末","愉快"]','주말 인사 표현입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(26,'키가 얼마나 크니?','你多高？','["你","多","高"]','多 + 단음절 형용사로 정도를 묻는 예문입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(27,'몸무게가 얼마나 나가니?','你多重？','["你","多","重"]','多 + 단음절 형용사로 정도를 묻는 예문입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(28,'몇 살이니? (10세 미만)','你几岁了？','["你","几","岁","了"]','자료에서는 10세 미만에게 묻는 표현으로 제시됩니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(29,'몇 살이니? (10세 이상)','你多大了？','["你","多","大","了"]','자료에서는 10세 이상에게 묻는 표현으로 제시됩니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(30,'연세가 어떻게 되세요?','您多大年纪了？','["您","多","大","年纪","了"]','웃어른의 나이를 묻는 정중한 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(31,'너희 가족은 몇 명이니?','你家有几口人？','["你","家","有","几","口","人"]','가족 수를 묻는 표현으로 口가 가족 인원 수의 양사로 쓰입니다.',NULL);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(32,'우리 가족은 네 명이야.','我家有四口人。','["我","家","有","四","口","人"]','가족 수를 口로 셉니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(33,'가족은 누구누구니?','家里有什么人？','["家里","有","什么","人"]','什么人으로 가족 구성원을 묻습니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(34,'아빠, 엄마, 누나 그리고 나야.','爸爸妈妈姐姐和我。','["爸爸","妈妈","姐姐","和","我"]','和로 명사를 연결합니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(35,'안녕하세요.','你好！','["你","好"]','기본 인사 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(36,'여러분 안녕하세요.','你们好！','["你们","好"]','복수 상대에게 하는 인사 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(37,'선생님, 안녕히 계세요!','老师，再见！','["老师","再见"]','작별 인사 표현입니다. 원문 표현 ‘再见！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(38,'내일 봐.','明天见！','["明天","见"]','시간 명사 + 见 형태의 작별 인사입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(39,'저녁에 보자.','晚上见！','["晚上","见"]','시간 명사 + 见 형태의 작별 인사입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(40,'선생님 안녕하세요.','老师好！','["老师","好"]','호칭 + 好 형태의 인사입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(41,'얘들아/학생들 안녕.','同学们好！','["同学","们","好"]','복수 접미 성격의 们이 쓰인 인사입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(42,'고마워요! (상대에게)','谢谢你！','["谢谢","你"]','감사 표현입니다. 원문 표현 ‘谢谢！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(43,'고마워.','谢谢你！','["谢谢","你"]','谢谢 뒤에 감사 대상을 붙일 수 있습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(44,'감사합니다.','谢谢您！','["谢谢","您"]','존칭 您을 사용한 감사 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(45,'천만에요. / 별말씀을요.','不客气！','["不","客气"]','감사 표현에 대한 대답입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(46,'별말씀을요.','不谢！','["不","谢"]','감사 표현에 대한 대답입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(47,'선생님, 죄송합니다!','老师，对不起！','["老师","对不起"]','대표적인 사과 표현입니다. 원문 표현 ‘对不起！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(48,'괜찮아요.','没关系！','["没","关系"]','사과에 대한 대답입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(49,'괜찮아요. / 아무 일 아니에요.','没事儿！','["没","事","儿"]','사과에 대한 대답으로 쓸 수 있습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(50,'정말 미안해요! / 정말 실례합니다!','真不好意思！','["真","不好意思"]','일상에서 对不起와 비슷하게 쓰는 표현입니다. 원문 표현 ‘不好意思！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(51,'감사합니다.','多谢！','["多","谢"]','보충자료의 감사 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(52,'정말 감사합니다.','非常感谢！','["非常","感谢"]','非常으로 감사의 정도를 강조합니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(53,'대단히 감사합니다.','十分感谢！','["十分","感谢"]','十分으로 감사의 정도를 강조합니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(54,'감사할 것 없어요.','不用谢！','["不用","谢"]','감사 표현에 대한 대답입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(55,'뭘 감사해요.','谢什么！','["谢","什么"]','감사 표현에 대한 대답입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(56,'별말씀을요.','哪里哪里！','["哪","里","哪","里"]','겸양의 답변으로 제시된 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(57,'정말 죄송합니다.','很抱歉！','["很","抱歉"]','보충자료의 사과 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(58,'정말 사과드립니다.','很道歉！','["很","道歉"]','보충자료의 사과 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(59,'선생님, 좋은 아침입니다!','老师，早！','["老师","早"]','아침의 짧은 인사입니다. 원문 표현 ‘早！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(60,'좋은 아침!','你早！','["你","早"]','아침 인사 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(61,'좋은 아침입니다.','早上好！','["早上","好"]','아침 시간대 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(62,'좋은 점심입니다.','中午好！','["中","午","好"]','점심 시간대 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(63,'좋은 오전입니다.','上午好！','["上","午","好"]','오전 시간대 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(64,'좋은 오후입니다.','下午好！','["下","午","好"]','오후 시간대 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(65,'좋은 저녁입니다.','晚上好！','["晚上","好"]','저녁 시간대 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(66,'잘 자요.','晚安！','["晚","安"]','잠들기 전 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(67,'내일 봐, 바이바이!','明天见，拜拜！','["明天","见","拜拜"]','친근한 작별 인사입니다. 원문 표현 ‘拜拜！’을 유지하면서 배열 연습용으로 호칭·대상·수식어 등을 덧붙인 예문입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(68,'잠시 후에 보자.','一会儿见！','["一会儿","见"]','가까운 미래의 재회를 나타내는 작별 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(69,'다음에 봐.','下次见！','["下","次","见"]','下次 + 见 형태의 작별 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(70,'오랜만입니다.','好久不见！','["好久","不见"]','오랜만에 만난 상대에게 하는 인사입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(71,'어서 오세요.','欢迎光临！','["欢迎","光临"]','가게·식당 등에서 손님을 맞는 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(72,'살펴 가세요.','慢走！','["慢","走"]','떠나는 손님에게 하는 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(73,'축하합니다.','恭喜恭喜！','["恭喜","恭喜"]','축하 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(74,'너는 이름이 뭐니?','你叫什么名字？','["你","叫","什么","名字"]','什么을 사용한 의문문에는 보통 吗를 함께 쓰지 않습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(75,'나는 징징이라고 해. 너는?','我叫晶晶，你呢？','["我","叫","晶","晶","你","呢"]','呢로 앞의 질문을 상대에게 되물을 수 있습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(76,'나는 김대한이라고 해.','我叫金大韩。','["我","叫","金","大","韩"]','叫를 이용해 이름을 말하는 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(77,'너를 알게 되어 기뻐.','认识你很高兴。','["认识","你","很","高兴"]','很 + 형용사 구조가 쓰였습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(78,'그는 이름이 뭐니?','他叫什么名字？','["他","叫","什么","名字"]','3인칭 주어로 이름을 묻는 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(79,'그는 왕둥이라고 해.','他叫王东。','["他","叫","王","东"]','叫 뒤에 이름을 둡니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(80,'나는 가. 너는?','我去，你呢？','["我","去","你","呢"]','呢로 상대방의 경우를 되묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(81,'나는 가지 않아.','我不去。','["我","不","去"]','동사 앞에 不를 두어 부정합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(82,'나는 바빠.','我很忙。','["我","很","忙"]','형용사 술어 앞에 很이 쓰였습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(83,'그녀는 예뻐.','她很漂亮。','["她","很","漂亮"]','형용사 술어 앞에 很이 쓰였습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(84,'너는 어느 나라 사람이니?','你是哪国人？','["你","是","哪","国","人"]','哪 + 国으로 어느 나라를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(85,'나는 중국인이야.','我是中国人。','["我","是","中国","人"]','是로 신분·국적을 연결합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(86,'그도 중국인이니?','他也是中国人吗？','["他","也","是","中国","人","吗"]','也는 술어 앞에 놓이고, 吗로 예/아니오 질문을 만듭니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(87,'아니, 그는 한국인이야.','不是，他是韩国人。','["不","是","他","是","韩国","人"]','是의 부정은 不是로 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(88,'나는 미국인이야.','我是美国人。','["我","是","美国","人"]','是 + 국적 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(89,'그는 일본인이 아니야.','他不是日本人。','["他","不","是","日本","人"]','不是로 국적을 부정합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(90,'그는 어느 나라 사람이니?','他是哪国人？','["他","是","哪","国","人"]','哪国人으로 국적을 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(91,'그는 스페인 사람이야.','他是西班牙人。','["他","是","西班牙","人"]','是 + 국적 표현입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(92,'너는 학생이니?','你是学生吗？','["你","是","学生","吗"]','평서문 끝에 吗를 붙여 예/아니오 의문문을 만듭니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(93,'아니야.','不是。','["不","是"]','是로 묻는 질문에 대한 부정 대답입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(94,'성함이 어떻게 되시나요?','您贵姓？','["您","贵","姓"]','상대의 성을 정중하게 묻는 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(95,'나는 김씨고, 김대한이라고 해.','我姓金，叫金大韩。','["我","姓","金","叫","金","大","韩"]','姓으로 성을, 叫로 이름을 말합니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(96,'처음 뵙겠습니다.','初次见面！','["初次","见面"]','첫 만남의 인사 표현입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(97,'생일 축하합니다!','祝你生日快乐！','["祝","你","生日","快乐"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(98,'주말 잘 보내세요.','祝你周末愉快！','["祝","你","周末","愉快"]','祝 + 사람 + 축원 내용의 구조입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(99,'정말 잘생겼다!','真帅！','["真","帅"]','真이 형용사 앞에서 정도를 강조합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(100,'이 사람은 누구야?','这是谁？','["这","是","谁"]','这와 谁를 사용한 의문문입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(101,'이 사람은 내 중국 친구야.','这是我的中国朋友。','["这","是","我","的","中国","朋友"]','的로 소유·수식 관계를 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(102,'이것은 책이야.','这是书。','["这","是","书"]','这는 가까운 사물·사람을 가리킵니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(103,'저것은 의자야.','那是椅子。','["那","是","椅子"]','那는 먼 사물·사람을 가리킵니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(104,'저것은 그녀의 책가방이야.','那是她的书包。','["那","是","她","的","书包"]','她的로 소유 관계를 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(105,'그는 몇 살이야?','他多大？','["他","多","大"]','多大로 나이·크기를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(106,'그는 열여덟 살이야.','他十八岁了。','["他","十","八","岁","了"]','숫자 + 岁로 나이를 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(107,'그는 키가 얼마나 커?','他多高？','["他","多","高"]','多 + 단음절 형용사로 정도를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(108,'만리장성은 얼마나 길어?','长城多长？','["长城","多","长"]','多 + 长으로 길이를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(109,'너는 남동생이 있니?','你有弟弟吗？','["你","有","弟弟","吗"]','有 문장 끝에 吗를 붙여 소유·존재 여부를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(110,'없어, 나는 오빠/형이 한 명 있어.','没有，我有一个哥哥。','["没有","我","有","一","个","哥哥"]','有의 부정은 没有입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(111,'그는 몇 학년이야?','他上几年级？','["他","上","几","年级"]','几로 학년 수를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(112,'그는 고등학교 3학년이야.','他上高中三年级。','["他","上","高中","三","年级"]','上 + 학교/학년으로 재학을 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(113,'나는 강아지가 있어.','我有小狗。','["我","有","小狗"]','有로 소유를 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(114,'그녀는 휴대전화가 없어.','她没有手机。','["她","没有","手机"]','没有로 소유 부정을 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(115,'너는 남동생이 몇 명 있니?','你有几个弟弟？','["你","有","几","个","弟弟"]','几 + 양사 个 + 명사 구조입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(116,'남동생이 두 명이야.','两个弟弟。','["两","个","弟弟"]','두 개를 셀 때 两 + 양사 구조가 쓰입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(117,'키가 얼마나 커?','你多高？','["你","多","高"]','多高로 키를 묻습니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(118,'1미터 75야.','1米75。','["1","米","75"]','키 수치를 말하는 보충자료의 예시입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(119,'몸무게가 얼마나 나가?','你多重？','["你","多","重"]','多重으로 무게를 묻습니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(120,'60킬로그램이야.','60公斤。','["60","公斤"]','무게 수치를 말하는 보충자료의 예시입니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(121,'몇 살이니?','你几岁了？','["你","几","岁","了"]','보충자료에서 10세 미만에게 쓰는 나이 질문으로 제시됩니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(122,'몇 살이니?','你多大了？','["你","多","大","了"]','보충자료에서 10세 이상에게 쓰는 나이 질문으로 제시됩니다.',1);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(123,'오늘은 몇 월 며칠이니?','今天是几月几号？','["今天","是","几","月","几","号"]','几月几号로 날짜를 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(124,'5월 7일이야.','五月七号。','["五","月","七","号"]','월은 月, 날짜는 号로 표현합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(125,'내일은 몇 월 며칠이니?','明天是几月几号？','["明天","是","几","月","几","号"]','시간 명사 + (是) + 几月几号 구조입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(126,'6월 8일이야.','六月八号。','["六","月","八","号"]','월은 月, 날짜는 号로 표현합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(127,'내일은 무슨 요일이니?','明天星期几？','["明天","星期","几"]','星期几로 요일을 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(128,'수요일이야.','星期三。','["星期","三"]','星期 + 숫자로 요일을 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(129,'오늘은 수요일이 아니야.','今天不是星期三。','["今天","不","是","星期","三"]','不是로 요일을 부정합니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(130,'지금 몇 시야?','现在几点？','["现在","几","点"]','几点으로 시각을 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(131,'4시 20분이야.','四点二十分。','["四","点","二","十分"]','点과 分으로 시각을 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(132,'우리 몇 시에 밥 먹어?','我们几点吃饭？','["我们","几","点","吃饭"]','주어 + 시간 질문 + 일과 표현의 구조입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(133,'6시 반에 밥 먹자.','六点半吃饭吧。','["六","点","半","吃饭","吧"]','半은 30분, 吧는 제안의 어감을 나타냅니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(134,'나는 5시에 집에 가.','我五点回家。','["我","五","点","回家"]','일과 문장에서 시간은 보통 동사 앞에 놓입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(135,'너는 몇 시에 밥 먹어?','你几点吃饭？','["你","几","点","吃饭"]','几点 + 일과 표현으로 시간을 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(136,'나는 6시 반에 밥을 먹어.','我六点半吃饭。','["我","六","点","半","吃饭"]','주어 + 시간 + 일과 표현의 어순입니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(137,'네 생일은 몇 월 며칠이야?','你的生日是几月几号？','["你","的","生日","是","几","月","几","号"]','生日 + 是几月几号로 생일을 묻습니다.',0);
INSERT INTO "sentences" ("id","korean","chinese","tokens","explanation","source") VALUES(138,'내 생일은 2월 10일이야.','我的生日是二月十号。','["我","的","生日","是","二","月","十","号"]','활동 예시의 날짜 표현을 문장으로 정리했습니다.',0);
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(1,'不에 대하여',replace('구조: 주어 + 不 + 동사/형용사\n不는 동사·형용사 앞에 놓여 부정을 나타냅니다. 교재 예시는 不多, 不看이며, 뒤에 제4성이 오면 보통 bú로 읽습니다.','\n',char(10)),'["不多。","不看。","我不去。","他不是日本人。"]','["多不。","我去不。"]','["부정","성조변화","초급"]','[{"type":"blank","prompt":"[不의 부정과 성조 변화] 我___去。","explanation":"구조: 주어 + 不 + 동사/형용사\n不는 동사·형용사 앞에 놓여 부정을 나타냅니다. 교재 예시는 不多, 不看이며, 뒤에 제4성이 오면 보통 bú로 읽습니다.","options":["不","吗","很","呢"],"answer":"不"},{"type":"error","prompt":"[不의 부정과 성조 변화] ‘我去不。’에서 어순상 고쳐야 할 부분은?","explanation":"구조: 주어 + 不 + 동사/형용사\n不는 동사·형용사 앞에 놓여 부정을 나타냅니다. 교재 예시는 不多, 不看이며, 뒤에 제4성이 오면 보통 bú로 읽습니다.","options":["不를 去 앞에 둔다","不를 문장 맨 앞에 둔다","吗를 추가한다","그대로 맞다"],"answer":"不를 去 앞에 둔다"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(2,'예/아니오 의문문',replace('구조: 평서문 + 吗？\n평서문 끝에 吗를 붙이면 예/아니오로 답하는 의문문을 만들 수 있습니다.','\n',char(10)),'["你是学生吗？","他也是中国人吗？","你有弟弟吗？"]','["吗你是学生？"]','["의문문","吗","초급"]','[{"type":"blank","prompt":"[吗를 이용한 예/아니오 의문문] 你是学生___？","explanation":"구조: 평서문 + 吗？\n평서문 끝에 吗를 붙이면 예/아니오로 답하는 의문문을 만들 수 있습니다.","options":["吗","呢","的","很"],"answer":"吗"},{"type":"order","prompt":"[吗를 이용한 예/아니오 의문문] ‘너는 남동생이 있니?’를 배열하세요.","explanation":"구조: 평서문 + 吗？\n평서문 끝에 吗를 붙이면 예/아니오로 답하는 의문문을 만들 수 있습니다.","tokens":["你","有","弟弟","吗"],"answer":"你有弟弟吗？"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(3,'의문문',replace('구조: 의문사를 포함한 의문문 (단순 의문문에서는 吗를 덧붙이지 않음)\n什么, 哪, 谁, 几 같은 의문사가 들어간 단순 의문문에는 보통 吗를 함께 쓰지 않습니다.','\n',char(10)),'["你叫什么名字？","你是哪国人？","这是谁？","他上几年级？"]','["你叫什么名字吗？","这是谁吗？"]','["의문문","의문사","吗"]','[{"type":"error","prompt":"[의문사와 吗] 你叫什么名字吗？에서 불필요한 부분은?","explanation":"구조: 의문사를 포함한 의문문 (단순 의문문에서는 吗를 덧붙이지 않음)\n什么, 哪, 谁, 几 같은 의문사가 들어간 단순 의문문에는 보통 吗를 함께 쓰지 않습니다.","options":["你","叫","什么","吗"],"answer":"吗"},{"type":"blank","prompt":"[의문사와 吗] 这___谁？","explanation":"구조: 의문사를 포함한 의문문 (단순 의문문에서는 吗를 덧붙이지 않음)\n什么, 哪, 谁, 几 같은 의문사가 들어간 단순 의문문에는 보통 吗를 함께 쓰지 않습니다.","options":["是","吗","很","有"],"answer":"是"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(4,'되묻기',replace('구조: 명사/대명사 + 呢？\n앞에서 나온 질문이나 화제를 상대에게 되물을 때 명사·대명사 뒤에 呢를 붙일 수 있습니다.','\n',char(10)),'["我叫晶晶，你呢？","我去，你呢？"]','["我叫晶晶，吗你？"]','["呢","의문문","회화"]','[{"type":"blank","prompt":"[呢로 되묻기] 我叫晶晶，你___？","explanation":"구조: 명사/대명사 + 呢？\n앞에서 나온 질문이나 화제를 상대에게 되물을 때 명사·대명사 뒤에 呢를 붙일 수 있습니다.","options":["呢","吗","不","的"],"answer":"呢"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(5,'형용사',replace('구조: 주어 + 很 + 형용사\n교재에서는 형용사 술어 앞에 很을 두는 형태를 제시합니다: 我很忙, 她很漂亮.','\n',char(10)),'["我很忙。","她很漂亮。"]','["我忙很。","她漂亮很。"]','["很","형용사","어순"]','[{"type":"order","prompt":"[很 + 형용사 술어] ‘그녀는 예뻐.’를 배열하세요.","explanation":"구조: 주어 + 很 + 형용사\n교재에서는 형용사 술어 앞에 很을 두는 형태를 제시합니다: 我很忙, 她很漂亮.","tokens":["她","很","漂亮"],"answer":"她很漂亮。"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(6,'판단과 부정판단',replace('구조: 주어 + 是/不是 + 명사\n是는 사람의 신분·국적 등을 연결하는 판단동사이며, 부정은 是 앞에 不를 둔 不是입니다.','\n',char(10)),'["我是中国人。","他不是日本人。"]','["我中国人是。","他是不日本人。"]','["是","부정","판단문"]','[{"type":"blank","prompt":"[是와 不是] 他___日本人。","explanation":"구조: 주어 + 是/不是 + 명사\n是는 사람의 신분·국적 등을 연결하는 판단동사이며, 부정은 是 앞에 不를 둔 不是입니다.","options":["不是","不","没有","没"],"answer":"不是"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(7,'也의 위치',replace('구조: 주어 + 也 + 술어\n也는 ‘~도’라는 뜻으로 보통 주어 뒤, 술어 앞에 놓입니다.','\n',char(10)),'["他也是中国人吗？"]','["他是也中国人吗？"]','["也","부사","어순"]','[{"type":"order","prompt":"[也의 위치] ‘그도 중국인이니?’를 배열하세요.","explanation":"구조: 주어 + 也 + 술어\n也는 ‘~도’라는 뜻으로 보통 주어 뒤, 술어 앞에 놓입니다.","tokens":["他","也","是","中国人","吗"],"answer":"他也是中国人吗？"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(8,'여기와 저기',replace('구조: 这/那 + 是 + 명사\n这는 가까운 사람·사물을, 那는 먼 사람·사물을 가리킬 때 사용합니다.','\n',char(10)),'["这是书。","那是椅子。","那是她的书包。"]','["这书是。","那椅子是。"]','["지시대명사","这","那"]','[{"type":"blank","prompt":"[这와 那] ___是椅子。 (저것은 의자야.)","explanation":"구조: 这/那 + 是 + 명사\n这는 가까운 사람·사물을, 那는 먼 사람·사물을 가리킬 때 사용합니다.","options":["那","这","谁","哪"],"answer":"那"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(9,'소유·수식',replace('구조: 소유자/수식어 + 的 + 명사\n명사나 대명사 뒤의 的는 뒤에 오는 명사를 꾸미거나 소유 관계를 나타냅니다.','\n',char(10)),'["这是我的中国朋友。","那是她的书包。"]','["那是她书包的。"]','["的","소유","수식"]','[{"type":"blank","prompt":"[的의 소유·수식] 那是她___书包。","explanation":"구조: 소유자/수식어 + 的 + 명사\n명사나 대명사 뒤의 的는 뒤에 오는 명사를 꾸미거나 소유 관계를 나타냅니다.","options":["的","吗","呢","很"],"answer":"的"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(10,'얼마나',replace('구조: 주어 + 多 + 형용사？\n多는 ‘많다’ 외에 ‘얼마나’의 뜻으로 단음절 형용사와 결합해 나이·높이·무게·거리·길이 등의 정도를 묻습니다.','\n',char(10)),'["他多大？","你多高？","你多重？","长城多长？"]','["你高多？"]','["多","정도","의문문"]','[{"type":"blank","prompt":"[多 + 단음절 형용사] 你___高？","explanation":"구조: 주어 + 多 + 형용사？\n多는 ‘많다’ 외에 ‘얼마나’의 뜻으로 단음절 형용사와 결합해 나이·높이·무게·거리·길이 등의 정도를 묻습니다.","options":["多","几","很","哪"],"answer":"多"},{"type":"blank","prompt":"[多 + 단음절 형용사] 长城多___？","explanation":"구조: 주어 + 多 + 형용사？\n多는 ‘많다’ 외에 ‘얼마나’의 뜻으로 단음절 형용사와 결합해 나이·높이·무게·거리·길이 등의 정도를 묻습니다.","options":["长","大","重","岁"],"answer":"长"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(11,'가지고 있거나 가지고 있지 않은 것',replace('구조: 주어 + 有/没有 + 명사\n有는 ‘있다, 가지고 있다’이고, 부정형은 不有가 아니라 没有입니다.','\n',char(10)),'["我有小狗。","她没有手机。","没有，我有一个哥哥。"]','["她不有手机。"]','["有","没有","소유","부정"]','[{"type":"blank","prompt":"[有와 没有] 她___手机。 (그녀는 휴대전화가 없다.)","explanation":"구조: 주어 + 有/没有 + 명사\n有는 ‘있다, 가지고 있다’이고, 부정형은 不有가 아니라 没有입니다.","options":["没有","不有","不是","不"],"answer":"没有"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(12,'몇',replace('구조: 几 + 양사 + 명사\n几는 ‘몇’이라는 뜻의 의문사로, 교재에서는 일반적으로 10 이하의 수량을 물을 때 사용한다고 설명합니다. 명사를 셀 때 양사를 함께 씁니다.','\n',char(10)),'["你有几个弟弟？","你家有几口人？"]','["你有几弟弟？"]','["几","양사","수량"]','[{"type":"blank","prompt":"[几 + 양사 + 명사] 你有几___弟弟？","explanation":"구조: 几 + 양사 + 명사\n几는 ‘몇’이라는 뜻의 의문사로, 교재에서는 일반적으로 10 이하의 수량을 물을 때 사용한다고 설명합니다. 명사를 셀 때 양사를 함께 씁니다.","options":["个","口","岁","点"],"answer":"个"},{"type":"blank","prompt":"[几 + 양사 + 명사] 你家有几___人？","explanation":"구조: 几 + 양사 + 명사\n几는 ‘몇’이라는 뜻의 의문사로, 교재에서는 일반적으로 10 이하의 수량을 물을 때 사용한다고 설명합니다. 명사를 셀 때 양사를 함께 씁니다.","options":["口","本","分","号"],"answer":"口"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(13,'둘과 이',replace('구조: 两 + 양사 + 명사\n‘두 개/두 명’처럼 양사 앞에서 2를 말할 때 교재 예시는 两个弟弟를 사용합니다.','\n',char(10)),'["两个弟弟。"]','["二个弟弟。"]','["两","양사","수사"]','[{"type":"blank","prompt":"[两 + 양사] ___个弟弟。 (남동생 두 명)","explanation":"구조: 两 + 양사 + 명사\n‘두 개/두 명’처럼 양사 앞에서 2를 말할 때 교재 예시는 两个弟弟를 사용합니다.","options":["两","二","几","多"],"answer":"两"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(14,'한 일',replace('구조: 一 + 뒤 음절의 성조 → 一의 읽기 변화\n보충자료 기준: 一가 단독으로 읽거나 끝에 오면 yī, 뒤에 제1·2·3성이 오면 yì, 뒤에 제4성이 오면 yí로 읽습니다.','\n',char(10)),'["一起 yìqǐ","一定 yídìng","一年 yìnián","第一 dìyī"]','["一起 yíqǐ","一定 yìdìng","第一 dìyì"]','["一","성조변화","발음"]','[{"type":"blank","prompt":"[一의 성조 변화] 一起의 연결 발음: ___ qǐ","explanation":"구조: 一 + 뒤 음절의 성조 → 一의 읽기 변화\n보충자료 기준: 一가 단독으로 읽거나 끝에 오면 yī, 뒤에 제1·2·3성이 오면 yì, 뒤에 제4성이 오면 yí로 읽습니다.","options":["yī","yí","yì","yi"],"answer":"yì"},{"type":"blank","prompt":"[一의 성조 변화] 一定의 연결 발음: ___ dìng","explanation":"구조: 一 + 뒤 음절의 성조 → 一의 읽기 변화\n보충자료 기준: 一가 단독으로 읽거나 끝에 오면 yī, 뒤에 제1·2·3성이 오면 yì, 뒤에 제4성이 오면 yí로 읽습니다.","options":["yī","yí","yì","yi"],"answer":"yí"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(15,'날짜 표현',replace('구조: 월수 + 月 + 일수 + 号\n날짜는 ‘월 + 月 + 일 + 号’로 나타내며, 几月几号로 날짜를 묻습니다. 교재는 일반적인 날짜·요일 문장에서 是를 생략할 수 있다고 설명합니다.','\n',char(10)),'["今天是几月几号？","五月七号。","明天是几月几号？","六月八号。"]','["五月号七。"]','["날짜","月","号","几"]','[{"type":"order","prompt":"[날짜 표현: 几月几号] ‘5월 7일’을 배열하세요.","explanation":"구조: 월수 + 月 + 일수 + 号\n날짜는 ‘월 + 月 + 일 + 号’로 나타내며, 几月几号로 날짜를 묻습니다. 교재는 일반적인 날짜·요일 문장에서 是를 생략할 수 있다고 설명합니다.","tokens":["五","月","七","号"],"answer":"五月七号。"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(16,'요일 표현',replace('구조: 星期 + 一~六 / 天 / 日\n요일은 星期 뒤에 숫자를 붙여 나타냅니다. 일요일은 星期天 또는 星期日로도 표현합니다.','\n',char(10)),'["星期一","星期三","星期六","星期天","星期日"]','["三星期"]','["요일","星期"]','[{"type":"blank","prompt":"[요일 표현: 星期 + 숫자] 수요일 = 星期___","explanation":"구조: 星期 + 一~六 / 天 / 日\n요일은 星期 뒤에 숫자를 붙여 나타냅니다. 일요일은 星期天 또는 星期日로도 표현합니다.","options":["三","四","二","天"],"answer":"三"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(17,'특별한 날짜',replace('구조: 생일의 주인 + 的生日 + 是 + 날짜 (교재 기준)\n교재 팁에서는 생일이나 기념일처럼 특별한 날의 날짜를 말할 때 是를 생략하지 않는다고 설명합니다.','\n',char(10)),'["你的生日是几月几号？","我的生日是二月十号。"]','["你的生日几月几号？"]','["日期","是","생일"]','[{"type":"blank","prompt":"[특별한 날짜의 是] 你的生日___几月几号？","explanation":"구조: 생일의 주인 + 的生日 + 是 + 날짜 (교재 기준)\n교재 팁에서는 생일이나 기념일처럼 특별한 날의 날짜를 말할 때 是를 생략하지 않는다고 설명합니다.","options":["是","有","在","很"],"answer":"是"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(18,'시각 표현',replace('구조: 시수 + 点 + 분수 + 分 / 시수 + 点 + 半\n点은 ‘시’, 分은 ‘분’을 나타냅니다. 一刻는 15분, 半은 30분, 三刻는 45분을 나타냅니다.','\n',char(10)),'["四点二十分。","两点一刻。","五点半。","十二点三刻。"]','["四分二十点。"]','["시간","点","分","刻","半"]','[{"type":"correct","prompt":"[시각 표현: 点·分·刻·半] ‘5시 30분’에 맞는 표현은?","explanation":"구조: 시수 + 点 + 분수 + 分 / 시수 + 点 + 半\n点은 ‘시’, 分은 ‘분’을 나타냅니다. 一刻는 15분, 半은 30분, 三刻는 45분을 나타냅니다.","options":["五点半","五分半","半五点","五点一刻"],"answer":"五点半"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(19,'2시',replace('구조: 两 + 点\n교재는 시각에서 ‘2시’를 二点이 아니라 两点으로 표현한다고 설명합니다.','\n',char(10)),'["两点。"]','["二点。"]','["시간","两","수사"]','[{"type":"blank","prompt":"[2시: 两点] 2시를 나타내는 표현: ___ (교재 기준)","explanation":"구조: 两 + 点\n교재는 시각에서 ‘2시’를 二点이 아니라 两点으로 표현한다고 설명합니다.","options":["两点","二点","两个点","两分"],"answer":"两点"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(20,'0시 0분 전',replace('구조: 差 + 남은 분수 + 分 + 다음 시각 + 点\n예: 差十分三点 = 3시 10분 전, 즉 2시 50분. 差五分八点 = 8시 5분 전, 즉 7시 55분. 원본의 구조 표기를 실제 연습 예문으로 보완했습니다.','\n',char(10)),'["差十分三点。","差五分八点。"]','["差十点三分。","差五点八分。"]','["시간","差"]','[{"type":"blank","prompt":"[差를 이용한 시각 표현] ‘~분 전’을 나타내는 시각 표현에 쓰는 글자는?","explanation":"구조: 差 + 남은 분수 + 分 + 다음 시각 + 点\n예: 差十分三点 = 3시 10분 전, 즉 2시 50분. 差五分八点 = 8시 5분 전, 즉 7시 55분. 원본의 구조 표기를 실제 연습 예문으로 보완했습니다.","options":["差","半","刻","号"],"answer":"差"},{"type":"order","prompt":"[差를 이용한 시각 표현] 3시 10분 전을 배열하세요.","explanation":"구조: 差 + 남은 분수 + 分 + 다음 시각 + 点\n예: 差十分三点 = 3시 10분 전, 즉 2시 50분. 差五分八点 = 8시 5분 전, 즉 7시 55분. 원본의 구조 표기를 실제 연습 예문으로 보완했습니다.","tokens":["差","十","分","三","点"],"answer":"差十分三点。"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(21,'일과 문장의 어순',replace('구조: 주어 + 시간 + 동작\n교재는 일과 표현에서 ‘주어 + 시간 + 일과 표현’ 어순을 제시합니다.','\n',char(10)),'["我五点回家。","我六点半吃饭。"]','["我回家五点。"]','["어순","시간","일과"]','[{"type":"order","prompt":"[일과 문장의 어순] ‘나는 5시에 집에 간다.’를 배열하세요.","explanation":"구조: 주어 + 시간 + 동작\n교재는 일과 표현에서 ‘주어 + 시간 + 일과 표현’ 어순을 제시합니다.","tokens":["我","五点","回家"],"answer":"我五点回家。"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(22,'제안',replace('구조: 제안하는 내용 + 吧\n교재에서는 吧를 제안 등의 어감을 나타내는 어기조사로 제시하며, 六点半吃饭吧와 같이 씁니다.','\n',char(10)),'["六点半吃饭吧。"]','["吧六点半吃饭。"]','["吧","어기조사","제안"]','[{"type":"blank","prompt":"[吧의 제안] 六点半吃饭___。 (6시 반에 밥 먹자.)","explanation":"구조: 제안하는 내용 + 吧\n교재에서는 吧를 제안 등의 어감을 나타내는 어기조사로 제시하며, 六点半吃饭吧와 같이 씁니다.","options":["吧","吗","呢","的"],"answer":"吧"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(23,'성 묻고 답하기',replace('구조: 주어 + 姓 + 성 / 你姓什么？\n상대의 성을 묻을 때 你姓什么？ 또는 정중하게 您贵姓？을 쓰고, 我姓 + 성으로 답할 수 있습니다.','\n',char(10)),'["您贵姓？","你姓什么？","我姓金。"]','["你什么姓？"]','["姓","자기소개","의문문"]','[{"type":"order","prompt":"[姓으로 성 묻고 답하기] ‘성이 무엇이니?’를 배열하세요.","explanation":"구조: 주어 + 姓 + 성 / 你姓什么？\n상대의 성을 묻을 때 你姓什么？ 또는 정중하게 您贵姓？을 쓰고, 我姓 + 성으로 답할 수 있습니다.","tokens":["你","姓","什么"],"answer":"你姓什么？"}]');
INSERT INTO "grammar_rules" ("id","title","explanation","correct_examples","wrong_examples","tags","questions") VALUES(24,'축하축하',replace('구조: 祝 + 사람 + 축원 내용\n보충자료의 축하 표현은 祝 뒤에 상대와 바라는 내용을 이어 말하는 형태를 반복해서 제시합니다.','\n',char(10)),'["祝你生日快乐！","祝你好运！","祝你身体健康！","祝你周末愉快！"]','["你祝好运！"]','["祝","축하","축원"]','[{"type":"blank","prompt":"[祝 + 사람 + 축원 내용] ___你生日快乐！","explanation":"구조: 祝 + 사람 + 축원 내용\n보충자료의 축하 표현은 祝 뒤에 상대와 바라는 내용을 이어 말하는 형태를 반복해서 제시합니다.","options":["祝","谢","请","有"],"answer":"祝"}]');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(1,'인사 문화','중국에서 일반적인 인사를 할 때 가장 가까운 방식은?','가볍게 고개를 숙이거나 손을 흔든다.','["허리를 깊게 숙여 절한다.","두 손을 바닥에 짚는다.","항상 포옹한다."]','교과서는 중국에서는 일반적으로 허리를 굽히지 않고 가볍게 고개를 숙이거나 손을 흔든다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(2,'인사 문화','상대가 차나 술을 따라 줄 때 손가락으로 탁자를 가볍게 치며 감사를 나타내는 예법은?','叩指礼(kòuzhǐlǐ)','["拱手(gǒngshǒu)","红包(hóngbāo)","春联(chūnlián)"]','보충자료는 叩指礼를 차나 술을 따라 줄 때 손가락을 구부려 탁자를 가볍게 치는 감사 예법으로 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(3,'전통 인사','공수(拱手)에서 교과서가 제시한 남성의 손 위치는?','왼손을 오른손 위에 놓는다.','["오른손을 왼손 위에 놓는다.","두 손을 등 뒤로 둔다.","양손을 편 채 마주 댄다."]','교과서의 전통 인사 설명에서는 남자는 왼손을 오른손 위에, 여자는 오른손을 왼손 위에 놓는다고 제시합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(4,'성씨 문화','교과서가 제시한 중국의 5대 성씨에 포함되는 것은?','王·李·张·刘·陈','["金·朴·崔·郑·姜","赵·钱·孙·周·吴","林·黄·蔡·杨·郭"]','교과서는 王, 李, 张, 刘, 陈을 중국의 5대 성씨로 제시하고 이들이 전체 성씨의 약 30.8%를 차지한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(5,'이름 문화','중국어 이름의 글자를 木子李, 弓长张처럼 쪼개어 말하는 이유는?','이름을 정확히 전달하기 위해서','["이름을 더 길게 만들기 위해서","성을 숨기기 위해서","외국어 발음을 적기 위해서"]','교과서는 중국어에 동음이의어가 많아 이름을 정확히 전달하려고 글자를 구성 요소로 나누어 말하기도 한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(6,'호칭 문화','성(姓) 앞에 老를 붙이는 경우로 교과서가 설명한 것은?','나이가 많거나 존경하는 사람·동료를 부를 때','["어린아이나 자신보다 낮은 위치에 있는 사람을 부를 때","가게의 손님이나 회사의 사원을 부를 때","외국인이나 타지인을 부를 때"]','교과서는 존경을 담아 성 앞에 老를 붙이는 호칭을 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(7,'호칭 문화','나이가 많은 사람이 젊은 사람을 친근하게 부를 때 성 앞에 붙일 수 있는 말은?','小','["老","大夫","教授"]','교과서는 나이가 더 많은 사람이 젊은 사람을 부를 때 성 앞에 小를 붙이기도 한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(8,'호칭 문화','보충자료에서 음식점 직원을 부를 때 쓰는 호칭은?','服务员(fúwùyuán)','["老板(lǎobǎn)","教授(jiàoshòu)","大夫(dàifu)"]','보충자료는 음식점 직원을 부를 때 服务员을 사용한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(9,'학교생활','중국의 새 학년이 시작하는 달로 교과서가 제시한 것은?','9월','["3월","1월","6월"]','교과서는 중국은 9월에 새 학년이 시작된다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(10,'학교생활','교과서가 소개한 중국 학교의 쉬는 시간 활동은?','눈 체조와 체조','["수영과 눈 체조","등산과 야구","가창과 축구"]','교과서는 건강한 눈을 위한 눈 체조와 전교생이 함께하는 체조 시간을 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(11,'학교생활','교과서가 소개한 중국 학교 점심시간의 특징은?','약 2시간이며 낮잠 시간이 있다.','["10분이며 식사를 하지 않는다.","약 2시간이며 항상 학교 밖에서 먹는다.","점심시간이 없지만 낮잠 시간은 있다."]','교과서는 점심시간이 약 2시간이고 체력을 보충할 수 있는 낮잠 시간이 있다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(12,'교육','중국의 대학 입학시험 이름은?','高考(gāokǎo)','["中考(zhōngkǎo)","会考(huìkǎo)","雅思(Yǎsī)"]','교과서는 중국의 대학 입학시험을 高考라고 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(13,'교육','교과서가 제시한 가오카오 실시 시기는?','매년 6월 7일~10일','["매년 3월 1일~3일","매년 9월 1일~4일","매년 11월 11일~14일"]','교과서는 가오카오를 매년 6월 7일~10일, 이틀에서 나흘에 걸쳐 실시한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(14,'시간 문화','중국 전역에서 공식적으로 사용하는 표준시는?','베이징 표준시','["톈진 표준시","상하이 표준시","서울광역시 표준시"]','교과서는 동서로 실제 태양시 차이가 크지만 전국이 베이징 표준시를 사용해 공식 시간이 같다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(15,'기념일','중국에서 5월 20일이 고백과 연결되는 이유로 교과서가 설명한 것은?','520의 발음이 비슷해서','["그날이 진시황의 결혼일이어서","520의 한자가 비슷해서","중국어 숫자 5가 결혼을 뜻해서"]','교과서는 5월 20일의 520 발음이 我爱你와 비슷해 좋아하는 사람에게 마음을 고백하는 날로 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(16,'기념일','11월 11일과 관련해 교과서가 소개한 것은?','솔로 데이','["중국의 설날","가오카오 시험일","단오절"]','교과서는 11월 11일을 솔로 데이이자 중국의 최대 쇼핑데이로 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(17,'전통 명절','춘절(春节)의 날짜는?','음력 1월 1일','["음력 5월 5일","음력 8월 15일","음력 12월 25일"]','교과서는 춘절을 중국의 최대 명절이자 한국의 설에 해당하는 명절로 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(18,'전통 명절','춘절에 악귀를 쫓고 평안을 기원하는 풍습으로 교과서가 소개한 것은?','폭죽을 터뜨리고 춘롄을 대문에 붙인다.','["월병을 달에 바친다.","용선 경기를 한다.","눈 체조를 한다."]','교과서는 춘절에 폭죽을 터뜨리고 춘롄을 붙이는 풍습을 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(19,'전통 명절','교과서가 소개한 춘절 음식의 지역 차이는?','북방은 饺子, 남방은 年糕','["북방은 月饼, 남방은 粽子","북방은 咖啡, 남방은 热狗","북방은 年糕, 남방은 饺子"]','교과서는 춘절에 북방에서는 饺子, 남방에서는 年糕를 먹는다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(20,'전통 명절','중추절(中秋节)의 날짜는?','음력 8월 15일','["음력 1월 1일","음력 5월 5일","양력 8월 15일"]','교과서는 중추절을 한국의 추석에 해당하는 명절로 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(21,'전통 명절','중추절의 대표 음식으로 교과서가 소개한 것은?','月饼(yuèbǐng)','["粽子(zòngzi)","饺子(jiǎozi)","年糕(niángāo)"]','교과서는 중추절에 보름달을 감상하고 월병을 먹는다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(22,'전통 명절','단오절(端午节)이 기리는 인물은?','굴원','["공자","배성현","두보"]','교과서는 단오절을 초나라 시인 굴원을 기리기 위한 날로 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(23,'전통 명절','단오절의 풍습으로 교과서가 소개한 것은?','粽子를 먹고 용선 경기를 한다.','["月饼을 먹고 달맞이를 한다.","红包를 주고받는다.","春聯을 대문에 붙인다."]','교과서는 단오절에 찹쌀밥을 대나무 잎에 싸서 찐 粽子를 먹고 용선 경기를 한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(24,'국기','보충자료에서 중국 국기의 이름으로 제시한 것은?','五星红旗(Wǔxīng-Hóngqí)','["太極旗","五星蓝旗","红星旗"]','보충자료는 중국 국기를 五星红旗라고 소개하며 가로세로 비율을 3:2로 제시합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(25,'행정구역','보충자료가 제시한 중국의 직할시 수는?','4개','["2개","5개","22개"]','보충자료는 베이징·톈진·상하이·충칭을 4개 직할시로 제시합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(26,'행정구역','보충자료가 제시한 특별행정구는?','홍콩과 마카오','["베이징과 상하이","시짱과 신장","하이난과 타이완"]','보충자료는 홍콩(香港)과 마카오(澳门)를 2개 특별행정구로 제시합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(27,'지역 문화','하얼빈의 冰灯节은 무엇을 이용한 축제인가?','얼음 조각 축제','["사모래 조각 축제","벚꽃 축제","용선 경기 축제"]','보충자료는 헤이룽장성 하얼빈의 冰灯节에서 쑹화강의 얼음으로 만든 조각품을 전시한다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(28,'문화유산','보충자료의 布达拉宫 설명에서 위치로 제시된 곳은?','라싸','["베이징","푸둥","하이난"]','보충자료는 포탈라궁을 시짱 자치구 라싸에 있는 궁전으로 소개하며 1994년 세계문화유산 지정 사실을 적고 있습니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(29,'도시 상징','东方明珠는 어느 도시의 대표적 상징물로 소개되는가?','상하이','["베이징","하얼빈","청두"]','보충자료는 푸둥 지역의 468m 방송 송수신 탑 东方明珠를 상하이의 대표적 상징물로 소개합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(30,'지리','보충자료에서 ‘동양의 하와이’로 소개한 지역은?','海南(하이난)','["西藏(티베트)","天津(톈진)","杭州(항저우)"]','보충자료는 하이난을 중국 최남단 섬으로 소개하며 연중 따뜻해 ‘동양의 하와이’라 불린다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(31,'언어 문화','보충자료가 외래어를 받아들이는 방식으로 구분한 세 범주는?','음역·의역·음의역','["한역·직역·역역","성조·성모·운모","간체·번체·병음"]','보충자료는 중국어 외래어를 음역, 의역, 음의역의 세 유형으로 나누어 예를 제시합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(32,'인구정책','보충자료 기준 한 가정 한 자녀 정책 시행 연도는?','1979년','["1966년","2016년","2021년"]','보충자료는 1979년 계획생육(计划生育) 정책을 실시했다고 정리합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(33,'인구정책','보충자료 기준 한 가정 두 자녀 허용 시기는?','2016년','["1979년","2008년","2021년"]','보충자료는 2016년 全面两孩 정책을 실시했다고 정리합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(34,'인구정책','보충자료 기준 한 가정 세 자녀 허용 시기는?','2021년','["1979년","2016년","2024년"]','보충자료는 2021년 全面三孩 정책을 실시했다고 정리합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(35,'세대 표현','八零后가 가리키는 사람은?','1980년대 출생자','["1970년대 출생자","1990년대 출생자","2000년대 이후 출생자"]','보충자료는 八零后를 1980년대 출생자를 가리키는 표현으로 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(36,'인구정책','보충자료에서 小皇帝가 생겨난 배경으로 설명한 것은?','한 자녀 정책','["왕실 교육 제도","고대 황제의 아들 호칭","대학 입시 제도"]','보충자료는 한 자녀 정책 이후 외동 자녀가 가정에서 황제처럼 대접받는다는 뜻에서 小皇帝라는 말이 생겼다고 설명합니다.');
INSERT INTO "culture_items" ("id","category","question","answer","distractors","explanation") VALUES(37,'인구정책','보충자료에서 黑孩子가 가리키는 것은?','호적에 오르지 못한 아이','["검은 옷을 입는 학생","야간 학교 학생","해외 입양을 마친 아이"]','보충자료는 당시 산아 제한 정책을 위반해 호적에 올리지 못한 아이들을 黑孩子라고 설명합니다.');
